#!/usr/bin/env python3
"""Generate synthetic, non-private UI fixtures in the ignored test-dist folder."""
from email.message import EmailMessage
from pathlib import Path
root=Path(__file__).resolve().parent.parent/'test-dist';root.mkdir(exist_ok=True)
mail=EmailMessage();mail['From']='Cosmic Team <hello@example.edu>';mail['To']='Reader <reader@example.edu>';mail['Subject']='A quieter place for your mail';mail['Date']='Tue, 20 Oct 2026 12:30:00 -0500'
mail.set_content('Welcome to Cosmic Mail.\n\nThis message stays on your Mac.\n\nVisit https://example.edu or contact hello@example.edu.')
mail.add_alternative('''<!doctype html><html><head><style>body { background: red }</style></head><body>
<h2>A little room to read.</h2><p>Welcome to <strong>Cosmic Mail</strong> — a quiet home for saved messages and accidental email links.</p>
<p>Open a message, browse an archive, or copy a recipient. No inbox to connect. No message to send.</p>
<blockquote>Read at your own pace. Your mail stays on your Mac.</blockquote>
<table><tr><th>Today</th><th>Next</th></tr><tr><td>Read a saved email</td><td>Browse a mailbox archive</td></tr></table>
<p><a href="https://example.edu/">Example website</a> · <a href="mailto:hello@example.edu?subject=Hello%20Cosmic">Email link</a></p>
<img src="https://example.edu/tracking-pixel" alt="Remote image not loaded"><script>document.body.innerHTML='UNSAFE'</script></body></html>''',subtype='html')
mail.add_attachment(b'Cosmic Mail synthetic attachment.\n',maintype='text',subtype='plain',filename='Read me.txt')
raw=mail.as_bytes();(root/'Welcome.eml').write_bytes(raw);(root/'Welcome.emlx').write_bytes(str(len(raw)).encode()+b'\n'+raw+b'\n<plist><dict/></plist>')
other=EmailMessage();other['From']='Reading Group <group@example.edu>';other['To']='Reader <reader@example.edu>';other['Subject']='Weekend reading notes';other['Date']='Mon, 19 Oct 2026 09:00:00 +0800';other.set_content('A plain-text message.\n\nSpaces   stay   in   place.\nAnd line breaks stay too.\n\nEnjoy your reading.')
(root/'Reading.mbox').write_bytes(b'From hello@example.edu Tue Oct 20 12:30:00 2026\n'+raw+b'\nFrom group@example.edu Mon Oct 19 09:00:00 2026\n'+other.as_bytes()+b'\n')
for name in ['cur','new']:(root/'Maildir'/name).mkdir(parents=True,exist_ok=True)
(root/'Maildir/cur/1.eml').write_bytes(raw);(root/'Maildir/new/2.eml').write_bytes(other.as_bytes())
if not (root/'README.md').exists():
    (root/'README.md').write_text('''# Local fixtures\n\nGenerated by `python3 scripts/make-fixtures.py`. All addresses and messages are synthetic.\n\n- Welcome.eml: HTML/plain alternatives, styles and remote resources to remove, one attachment, and two links.\n- Welcome.emlx: same message plus Apple-style byte count and trailing metadata.\n- Reading.mbox: two messages for lazy archive navigation.\n- Maildir/: equivalent cur/new folder layout.\n\nKeep screenshots, fuzz seeds, and manual test notes here. Never put real mail in Git.\n''')
